import{clamp as s}from"./math.js";export function createExtent(i,g,v){return(function(a,h,l,w,x){if(!a)return;if(!h&&!g)return a;const u=g?0:l[0]*h,p=g?0:l[1]*h,d=x?x[0]:0,X=x?x[1]:0;let m=i[0]+u/2+d,o=i[2]-u/2+d,f=i[1]+p/2+X,M=i[3]-p/2+X;m>o&&(m=(o+m)/2,o=m),f>M&&(f=(M+f)/2,M=f);let Y=s(a[0],m,o),n=s(a[1],f,M);if(w&&v&&h){const t=30*h;Y+=-t*Math.log(1+Math.max(0,m-a[0])/t)+t*Math.log(1+Math.max(0,a[0]-o)/t),n+=-t*Math.log(1+Math.max(0,f-a[1])/t)+t*Math.log(1+Math.max(0,a[1]-M)/t)}return[Y,n]})}export function none(i){return i}
